```ts
import type { GeospatialCamera } from "@babylonjs/lite";

export function centerOnLatLon(camera: GeospatialCamera, latitudeDeg: number, longitudeDeg: number): void {
    const R = camera.limits.planetRadius;
    const lat = (latitudeDeg * Math.PI) / 180;
    const lon = (longitudeDeg * Math.PI) / 180;

    const x = R * Math.cos(lat) * Math.cos(lon);
    const y = -R * Math.cos(lat) * Math.sin(lon);
    const z = R * Math.sin(lat);

    camera.center = { x, y, z };
}
```

I wrote `src/center-on.ts` which converts the given latitude/longitude to a 3D point on the planet sphere using the geospatial camera's coordinate convention (north = +Z, east = −Y, prime meridian = +X, per note 54 and the default centre (R,0,0) from note 44), then assigns a new object to `camera.center` so the re-orbit happens immediately (per note 11). Yaw, pitch, and radius are untouched. I was not sure of anything in particular—the mapping is straightforward given the notes.
